const out = [];
try {
  const r = await fetch("https://kroki.io/plantuml/svg", {
    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: "@startuml\nPerson(p, \"P\")\nSystem(s, \"S\")\nRel(p, s, \"uses\")\n@enduml",
  });
  out.push({ status: r.status, type: r.headers.get("content-type") });
  const text = await r.text();
  out.push({ len: text.length, head: text.slice(0, 200) });
} catch (e) {
  out.push({ error: String(e) });
}
return out;

